import { requirePermission } from "@/lib/auth/guards"; import { getDashboard } from "@/lib/dashboard/queries"; import { MonthlyUnitSummary } from "@/components/dashboard/monthly-unit-summary"; import { ExpiringSoonPanel } from "@/components/dashboard/expiring-soon-panel"; import { DueMaintenancePanel } from "@/components/dashboard/due-maintenance-panel"; import { UnpaidBalancesPanel } from "@/components/dashboard/unpaid-balances-panel";
export default async function DashboardPage(){await requirePermission("view_dashboard");const month=new Date().toISOString().slice(0,7);const data=await getDashboard(month);return <section className="mx-auto w-full max-w-4xl space-y-6 px-4 py-6"><h1 className="text-2xl font-semibold">Dashboard</h1><MonthlyUnitSummary rows={data.summary??[]}/><ExpiringSoonPanel items={data.expiry??[]}/><DueMaintenancePanel items={data.maintenance??[]}/><UnpaidBalancesPanel items={data.balances??[]}/></section>}
