import { createSupabaseServerClient } from "@/lib/supabase/server"; import { requirePermission } from "@/lib/auth/guards"; import { dashboardMonthSchema } from "@/lib/validation/dashboard"; import { demoMode, demoDocuments, demoUnits } from "@/lib/demo/mode";
export async function getDashboard(month:string){await requirePermission("view_dashboard");const m=dashboardMonthSchema.parse(month);if(demoMode)return {summary:demoUnits.map((u)=>({unit_id:u.id,body_number:u.body_number,remittance_paid_centavos:18000,total_expense_centavos:185000})),expiry:demoDocuments.map((d)=>({...d,bucket:"due_30"})),maintenance:[],balances:[]};const s=await createSupabaseServerClient();const [{data:summary},{data:expiry},{data:maintenance},{data:balances}]=await Promise.all([s.rpc("dashboard_monthly_unit_summary",{month_start:`${m}-01`}),s.rpc("expiring_documents",{as_of:new Date().toISOString().slice(0,10)}),s.rpc("due_maintenance",{as_of:new Date().toISOString().slice(0,10)}),s.rpc("driver_outstanding_balances",{as_of:new Date().toISOString().slice(0,10)})]);return {summary,expiry,maintenance,balances};}
